from collections import Counter
from typing import Iterable

from .models import Discrepancy, Row


def find_discrepancies(left_rows: Iterable[Row], right_rows: Iterable[Row]) -> list[Discrepancy]:
    left_list = list(left_rows)
    right_list = list(right_rows)

    discrepancies: list[Discrepancy] = []

    # Create lookup by (merchant_order_id, provider_txn_id)
    left_counter: Counter[tuple[str, str]] = Counter()
    left_rows_by_key: dict[tuple[str, str], list[Row]] = {}
    for row in left_list:
        key = (row.merchant_order_id, row.provider_txn_id)
        left_counter[key] += 1
        left_rows_by_key.setdefault(key, []).append(row)

    right_by_key: dict[tuple[str, str], Row] = {}
    for row in right_list:
        key = (row.merchant_order_id, row.provider_txn_id)
        right_by_key[key] = row

    # Check for duplicates in left
    for key, count in left_counter.items():
        if count > 1:
            row = left_rows_by_key[key][0]
            discrepancies.append(
                Discrepancy(
                    kind="duplicate_left",
                    merchant_order_id=row.merchant_order_id,
                    provider_txn_id=row.provider_txn_id,
                    detail=f"appears {count} times in left"
                )
            )

    # Check for missing_right (in left but not in right)
    for key in left_counter:
        if key not in right_by_key:
            row = left_rows_by_key[key][0]
            discrepancies.append(
                Discrepancy(
                    kind="missing_right",
                    merchant_order_id=row.merchant_order_id,
                    provider_txn_id=row.provider_txn_id,
                    detail="found in left but not in right"
                )
            )

    # Check for missing_left (in right but not in left)
    for key in right_by_key:
        if key not in left_counter:
            row = right_by_key[key]
            discrepancies.append(
                Discrepancy(
                    kind="missing_left",
                    merchant_order_id=row.merchant_order_id,
                    provider_txn_id=row.provider_txn_id,
                    detail="found in right but not in left"
                )
            )

    # Check for amount_mismatch (in both but different amounts)
    for key in left_counter:
        if key in right_by_key:
            left_row = left_rows_by_key[key][0]
            right_row = right_by_key[key]
            if left_row.amount_cents != right_row.amount_cents:
                discrepancies.append(
                    Discrepancy(
                        kind="amount_mismatch",
                        merchant_order_id=left_row.merchant_order_id,
                        provider_txn_id=left_row.provider_txn_id,
                        detail=f"left={left_row.amount_cents} right={right_row.amount_cents}"
                    )
                )

    return discrepancies
